from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1];A=R/'assets';T=json.loads((A/'tokens.json').read_text());pages=[]
def p(tag,title,lead,body,dark=False):pages.append((tag,title,lead,body,dark))
def note(x):return '<aside>'+x+'</aside>'
def h(x):return '<h2>'+x+'</h2>'
def txt(x):return '<p>'+x+'</p>'
def rows(*items):return '<dl>'+''.join('<dt>'+k+'</dt><dd>'+v+'</dd>' for k,v in items)+'</dl>'
def table(head,*rr):return '<table><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r)+'</tr>' for r in rr)+'</table>'
def img(k,cap=''):return f'<figure><img src="models/print/{k}.jpg"><figcaption>{cap}</figcaption></figure>'
def grid(*xs):return '<div class="grid">'+''.join('<div class="cell">'+x+'</div>' for x in xs)+'</div>'
def badge(x):return '<span class="badge">'+x+'</span>'
p('BRAND & PRODUCT DESIGN SYSTEM  /  1.0','حرّر بلا حدود.','MAX EDITOR — Edit Beyond Limits.', '<div class="cover"><img src="assets/logo/mark-metal.svg"><b>MAX EDITOR</b><small>PRODUCT DESIGN OFFICE　 /　 DIRECTION 01</small></div>'+txt('وثيقة المالك 1.0 هي المرجع الاستراتيجي المعتمد. هذا الدفتر ترجمة تصميمية مقترحة لها، وليس اعتمادًا نهائيًا للرسوم أو إذنًا بتنفيذها.')+note('المسار الذي يوحّد النماذج: مشروع «رحلة الجبل» ← اختيار عنوان على T1 ← تعديل التحجيم عند 00:02.400 ← مراجعة الناتج. لا تتبدّل هوية المشروع بتبدّل حجم الشاشة.'),True)
p('01  /  STRATEGY','الوعد: قوة يمكن الوصول إليها','يبدأ صانع المحتوى بقطعة واحدة. تتّسع مساحة العمل عندما يصبح السؤال: ماذا أفعل بهذه الطبقة، وفي أي لحظة؟',rows(('لمن نصمّم؟','لصانع محتوى يريد إنجاز قص سريع، ولمحرر مستقل يريد دقة زمنية، ولمصمم حركة يحتاج مفاتيح ومنحنيات. الجمهور المستقبلي يعمل على مساحات واسعة أو ينقل المشاريع، وليس استخدام الكمبيوتر شرطًا لاحتراف الهاتف.'),('موضعنا في السوق','نتعلم سرعة الوصول إلى المهمة من CapCut، وعمق خصائص الطبقة من Alight Motion، ووضوح المسار الأساسي من InShot. لا نستعير شكل أشرطتها أو ألوانها، ولا ندّعي أن الطبقات أو المفاتيح اختراعات حصرية.'),('شخصية العلامة','احترافية ودقيقة: الرقم الفعلي بدل وصف «فائق». قوية وواثقة: فعل واحد واضح لكل قرار. فاخرة: سطوح هادئة وفراغ كافٍ. إبداعية: المعاينة هي صاحبة اللون، لا الزخرفة حولها.'),('لغة المنتج','نقول «حدّد البداية عند المؤشّر» لا «اكتشف سحر القص». نقول «تعذّر فتح المصدر؛ المشروع محفوظ» فقط إذا كانت اللقطة محفوظة. لا نَعِد بتسريع أو جودة لم تُقَس. الرسالة الإنجليزية تؤدي المعنى نفسه دون ترجمة حرفية.'),('طبقات التعقيد','المستوى الأول: اختيار ← معاينة ← قص ← تصدير. الثاني: تحديد عنصر يفتح نوع خصائصه. الثالث: توسيع الخاصية وحدها إلى مفاتيح ومنحنى. نفس الزمن ونفس زر الرجوع في المستويات الثلاثة.'))+note('الأولوية: أساس موثوق وواجهة متكيفة أولًا؛ تحريك ومزج ونص وصوت متقدم ثانيًا؛ قوالب وذكاء اصطناعي ونقل مشاريع وإصدار كمبيوتر لاحقًا. كل بند مقترح يحتاج مواصفة وقبولًا مستقلين.'))
p('02  /  BRAND MARK','نظام الشعار، لا صورة واحدة','احتفظنا بدراسة M في المرحلة A وبالقطع المائل والفراغ بين الساقين. التدرّج هو تشطيب، وليس شرط قراءة الحرف.', '<div class="logoStrip"><img src="assets/logo/lockup-dark.svg"><img src="assets/logo/lockup-light.svg"></div>'+rows(('على الداكن والفاتح','على الداكن: العلامة المعدنية واسم أبيض. على الفاتح: ذهب حِبري أدكن واسم فحمي بلا توهج. تُستخدم نسخة الحبر الواحد عند النقش أو التلوين المنظومي، والمعكوسة البيضاء فوق سطح داكن محكوم.'),('Android','لوحة 108×108 لكل من طبقة الخلفية والأمامية، ومسار أحادي للرمز الملوّن من النظام. أقصى إحداثيات جسم الحرف تقريبًا 26…82 على المحور الأفقي؛ يبقى داخل المركز عند القص. الملفات SVG مصادر تصميم وليست موارد Android XML أو أيقونات مثبتة.'),('الحجم والمساحة','اترك عرض ساق حول الرمز. في شريط ضيّق استخدم الحرف وحده بحجم مرئي 24–32dp. في رأس شاشة كبيرة استخدم القفل الأفقي. لا تضف العبارة التسويقية إلى أيقونة المشغّل الصغيرة.'),('الاستخدامات','Splash: ختم على خلفية نظيفة، ثم دخول بلا تأخير مصطنع. فتح مشروع: علامة ثابتة واسم المهمة. المتجر والموقع والدليل: توقيع في زاوية ذات تباين ثابت لا فوق التفاصيل المزدحمة.'))+grid('<b>صحيح</b><p>الحرف ثابت النِّسب؛ تدرّج لطيف وفي المواد الكبيرة فقط يمكن إضافة هالة خافتة خارج المتجه.</p>','<b>خاطئ</b><p>تمديد أفقي، لمعان متحرك دائم، قص حرف من لوحة صور، أو كلمة عربية داخل المنطقة الآمنة للأيقونة.</p>')+note('مرجع الاختيار الأصلي (الصورة الأولى في الصف الثالث) غير متوفر. لا ندّعي التطابق الحرفي؛ تبقى الهندسة والقفل الطباعي خاضعين لاعتماد المالك.'))
roles=['قماش العمل','سطوح الأدوات','خلفية التحديد','فعل رئيسي أو موضع','حافة تركيز ومقبض','عمق العلامة فقط','نص رئيسي','قيم وإرشاد','فواصل زخرفية','فشل مع وصف','نجاح مؤكد']
def lum(h):
 v=[int(h[i:i+2],16)/255 for i in (1,3,5)];return sum(a*(c/12.92 if c<=.04045 else ((c+.055)/1.055)**2.4) for c,a in zip(v,[.2126,.7152,.0722]))
def ratio(a,b):x,y=sorted((lum(a),lum(b)));return f'{(y+.05)/(x+.05):.2f}:1'
p('03  /  FOUNDATIONS','لون للفعل، لا للتزيين','تُسمّى القيم بحسب الدور لا بحسب الشاشة. تتشارك التسويقات والواجهة البصمة، لكن لا تتحوّل المعاينة إلى صورة ذهبية.', '<div class="swatches">'+''.join(f'<div><i style="background:{v}"></i><bdi>{v}</bdi><small>{r}</small></div>' for (k,v),r in zip(T['color'].items(),roles))+'</div>'+rows(('حكم التباين','نص داكن #101010 على زر #D9A52E: '+ratio('#101010','#D9A52E')+'؛ نص أبيض عليه: '+ratio('#FFFFFF','#D9A52E')+'، لذا لا يُعتمد الأبيض. #B8B2A5 على #191919: '+ratio('#B8B2A5','#191919')+'. هذه نسب محسوبة لا اختبار مستخدم. هدف النص العادي ≥4.5:1، وعناصر التحكم الضرورية ≥3:1 في اللغتين.'),('النص المختلط','Tajawal للعربية واللاتينية؛ Regular 400 للمتن والحقول، Medium 500 للأزرار والتسميات، Bold 700 للعناوين القصيرة. Arial بديل للاتينية فقط. روعيت مساحة إضافية للالتفاف بدل ضغط الحروف؛ تُعرض مقارنة الخطين في ص٢١. زمن ثابت العرض في حقل LTR مع عزل bidi لأسماء مثل Ridge.mp4. التدرّج 32/42 للعرض، 24/34 للشاشة، 18/28 للقسم، 16/26 للمتن، 14/22 للتسمية، 12/18 للزمن (sp/ارتفاع السطر).'),('القوالب الصغيرة','شبكة مسافات 4، 8، 12، 16، 24، 32dp. نصف قطر 8 للتحكم و12 للبطاقة و20 للدرج. حد 1 للفاصل و2 للتحديد؛ تركيز واضح مستقل عن اللون. الظل محصور في الطبقات الطافية، ولا يُستخدم لإبراز كل بطاقة.')))
names='استيراد،فيديو،صورة،صوت،نص،تشذيب،تقسيم،دمج،تراجع،إعادة،تشغيل،إيقاف،طبقات،انتقال،مؤثر،سرعة،تصدير،إعدادات،حذف،حفظ،تكبير،تصغير،مستوى،تدوير،حجم،تكرار،إضافة،مفتاح،منحنى،قناع،مزج،محاذاة،قفل،رؤية'.split('،');src=json.loads((A/'symbols-source.json').read_text());sheet='<div class="atlas">'+''.join(f'<div><svg viewBox="0 0 24 24"><path d="{d}"/></svg><small>{n}</small></div>' for d,n in zip(src.values(),names))+'</div>'
p('04  /  CONTROLS','قاموس الأوامر والمكوّنات','توسعة لأيقونات المرحلة A: المفتاح المعيّن، منحنى زمني، قناع، مزج، محاذاة، قفل ورؤية. لا رموز تعبيرية.',sheet+rows(('عائلة الخط','شبكة 24 وسُمك 1.7 ونهايات مستديرة. الرمز 20–24dp داخل هدف لمس ≥48dp. الأيقونة المحدّدة ذهبية مع إطار وتسمية؛ المعطّلة معها سبب. المعيّن يعني مفتاحًا وليس نجمة «مفضلة».'),('عقد المكوّن','ToolRail يأخذ الأوامر المتاحة والاختيار؛ Inspector يأخذ نوع العنصر وخصائصه؛ TimeRuler يأخذ زمنًا ومقياسًا؛ ExportStatus يأخذ حالة المهمة. الإيماءة ترسل نية تحرير، ولا تكتب Widget المشروع.'),('نماذج الضبط','حقل رقمي مع وحدة وعنوان دائم، مسودة ثم تأكيد/إلغاء. قائمة واحدة فوق المحتوى تعيد التركيز إلى مُطلقها. أمر مدمر يذكر اسم العنصر ويميّز حذف القطعة عن حذف الملف. الخطأ محلي، والتقدم لا يتظاهر بمعرفة النسبة.')))
p('05  /  GRAMMAR','بصمة المحرّر: محور، مرساة، نافذة','محور الزمن رفيع وثابت، ومرساة التحديد تربط نفس العنصر في ثلاث مناطق، ونافذة الخصائص واحدة مهما تغيّر عرض الجهاز.',table(['ما يفعله المستخدم','الأثر المرئي','قاعدة عدم الالتباس'],['يختار عنوان T1','حد حول النص، وحدا القطعة، واسم T1 في المفتش','الزمن لا يقفز عند مجرد التحديد.'],['يسحب طرف القطعة','تظليل المسودة وقراءة البداية/النهاية والمدة','تحريك المقبض ≠ تحريك المؤشر. عند التراجع تحفظ البيانات السابقة.'],['ينقل طبقة أو عنصرًا','ظل موضع قديم وخط إدراج أو دليل محاذاة','تُحفظ الهوية عند النقل؛ القفل يمنع الكتابة. إلغاء خارج الهدف يعيد المسودة.'],['يضغط معيّن خاصية','مفتاح عند زمن قابل للتعديل وقيمة رقمية','الضغط على مفتاح موجود يحدده، لا يضيف نسخة فوقه.'],['يبدّل الأداة','يتغير محتوى المفتش فقط؛ المعاينة والمسطرة ثابتتان','لا نفتح أدراجًا متداخلة أو نشغّل معاينات بطاقات بالتوازي.'],['يتراجع ثم يعيد','يتغيّر محتوى المشروع بعد نجاح الأمر، ويظهر وصفه','لا ندّعي استعادة تاريخ Undo بعد إغلاق التطبيق.'])+h('رحلة المستخدم عبر الشاشات')+txt('بدء ← مكتبة مشاريع مقترحة ← مشروع جديد ← منتقي النظام ← محرّر. من المحرّر: تحديد ← مفتش ← معاينة مسودة ← تطبيق أو إلغاء. التصدير فرع ينتهي بملف مؤكد أو عودة إلى نفس المشروع. الإعدادات تغيّر اللغة وتعيد المستخدم إلى موضعه.')+note('مسار Android المثبت اليوم يبدأ من تحرير فيديو واحد. مكتبة متعددة، نصوص ومفاتيح ظاهرة في النماذج أهداف تصميم، لا سجلات مشاريع فعلية. يحتفظ دفتر المرحلة A بالتفاصيل السابقة للشاشات الإحدى عشرة.'))
p('06  /  COMPACT','الهاتف بالطول: اليد قبل اللوحة','دراسة 390 × 844. المُحدّد عنوان T1، والخاصية Scale، والزمن 00:02.400.', '<div class="phoneSpread">'+img('phone')+'<div>'+rows(('ترتيب النظر','المعاينة أولًا، النقل والوقت تحتها، ثم مسطرة ومسارات. الشريط السفلي يفتح مفتش العنصر المختار. حافة الذهب الصغيرة خلف النص تؤكد أنه هدف التحرير ولا تظهر في الناتج.'),('العمل السريع','عند عدم وجود تحديد يُطوى المفتش؛ يبقى تشغيل وقص وتصدير في المتناول. عند تحديد العنوان يظهر اسمه وخصائصه، ويمكن توسيع المفتش إلى محرر قيمة.'),('المساحة الضيقة','القطعة المختارة لا تُخفى خلف الدرج. عند ارتفاع قصير تُطوى المسارات غير المحددة وتظل أسماؤها قابلة للكشف. حقلا الزمن والتكبير بديلان عن مقبضين متقاربين.'),('اليد واللغة','الشريط يتمرر أفقياً، ولا تُصغّر أهداف اللمس. ترتيب القراءة RTL، لكن زمن المشروع يزيد نحو اليمين. عند تكبير النص يُسمح بسطرين أو تسمية بديلة، لا اقتطاع زر التأكيد.'))+'</div></div>')
p('07  /  SHORT WIDE','الهاتف بالعرض: إعادة توزيع لا تكبير','نفس المشروع عند تدوير الجهاز. القصير في الارتفاع له أولوية على عتبة عرض اللوحي.',img('land','850 × 393 • نقل المفتش إلى طرف المعاينة وإظهار ثلاثة مسارات ذات أولوية')+rows(('ما تحرّك؟','الدرج السفلي يصبح مفتشًا جانبيًا مضغوطًا. أُخفيت مكتبة المصادر الدائمة وطُويت مسارات الصورة والمؤثر في الدراسة. تُكشف المسارات من أمر الطبقات في النسخة المقترحة؛ الطي لا يحذفها.'),('ما بقي؟','الوقت 00:02.400، والعنوان محدّد على T1، والمسار الرئيس والصوت مربوطان بالمسطرة نفسها. لا أمر تعديل عند الدوران، ولا مراجعة جديدة للمشروع.'),('مساحة مستحيلة','إذا لم تبقَ مساحة معاينة مريحة، يُعرض المفتش عند الطلب بدل تثبيته. يستعاد التركيز على نفس الخاصية بعد تبديل التخطيط. لا نخفي أوامر التشغيل لإجبار العرض الجانبي.')))
p('08  /  EXPANDED ANDROID','شاشة واسعة: ثلاث مناطق عمل','دراسة Android لوحي 1120 × 750. لم نضع شاشة الهاتف داخل إطار أكبر.',img('wide','مكتبة عند بداية الاتجاه • معاينة وسطية • خصائص عند نهايته • زمن مشترك أسفل العرض')+rows(('السلوك','تحديد صف في المكتبة لا يساوي إضافة أصل. اختيار قطعة من الزمن يحدّث المفتش الجانبي، ويبقى مكان المشروع والوقت واضحين. لوحة المفاتيح والفأرة دعم إضافي؛ يبقى مسار اللمس متاحًا.'),('حدود إرشادية','أقل من 600dp تخطيط مدمج؛ 600–839 متوسط مع لوحة واحدة قابلة للطي؛ ≥840dp وارتفاع كافٍ يتيح لوحتين بشرط بقاء ≥320dp للمعاينة. تُقدّم حالة الارتفاع <480dp في الوضع الأفقي. هذه نقاط بدء تقاس لاحقًا لا تعريف لنوع الجهاز.')))
p('09  /  DESKTOP STUDY','الكمبيوتر: مساحة عمل مستقلة','دراسة LTR بالإنجليزية 1380 × 800. نفس العلامة ومصطلحات الزمن، لكن أدوات إدخال مختلفة.',img('desk','Desktop concept only • Media bin / monitor / inspector + docked sequence')+rows(('اقتراح خاص بالكمبيوتر','قوائم أوامر وبحث، مناطق إرساء يمكن نقلها وإعادة ضبط ترتيبها، مكتبة لقبول سحب الملفات وإفلاتها، وتكبير زمني حول مؤشر الفأرة. مفاتيح مقترحة: Space للتشغيل، Ctrl/Cmd+Z للتراجع، وأسهم للتنقل إطارًا؛ لا تُلتقط عند تحرير نص.'),('الفصل عن Android','مشروع دراسة منفصل للمقدرات: اختيار ملفات محلي، منح الوصول وإعادة ربطه، codecs، تسريع GPU، نافذة وإدخال واختبارات تصدير على كل نظام. لا يُفترض تشغيل Kotlin/Media3 خارج Android أو قابلية نقل URI إلى كمبيوتر. لا قرار محرك بديل هنا.')))
p('10  /  TIME & SELECTION','مسارات متعدّدة، ساعة واحدة','مواصفة تفاعل مستقبلية؛ العقد المعتمد باقٍ كما هو حتى قرار مستقل.',table(['الكيان','كيف يظهر','ما الذي يتطلب تحقّقًا'],['V1 / فيديو رئيسي','مصغرات ومقابض بداية ونهاية؛ بعد القص تظهر مدة التحديد.','لا مساواة بين تغيير موضع التشغيل وتعديل النطاق.'],['P1 / صورة وT1 / نص','لون حيادي لكل عائلة مع رمز واسم؛ شارة T1 عبر المفتش والزمن.','إظهار وترتيب وتوقيت كل عنصر، واستعادة التحديد بمعرف مستقر.'],['A1 / صوت','موجة مشتقة من البيانات، لا موجة وهمية أثناء التحميل.','الانزياح عند المزامنة يُحسب بالزمن، لا بالبكسلات.'],['FX / أثر أو وصلة','منطقة مرتبطة بالعنصر؛ الانتقال عند حد مقطعين له مدة.','لا اختراع أثر مستقل أو تداخل لا يصفه العقد.'] )+rows(('حفظ الحالة عند إعادة التخطيط','فصل هوية المشروع وrevision والنطاقات الدائمة عن جلسة العرض: selectedId، positionUs، مستوى التكبير، موضع التمرير والخاصية المفتوحة. إعادة توزيع اللوحات تغير العرض فقط. إذا زال المحدد بعد أمر صالح، ينتقل التركيز لأقرب عنصر صالح بإعلان واضح.'),('ضبط الزمن','الزمن المرجعي بالميكروثانية. نطاق القص نصف مفتوح. مفاتيح القطعة بزمن الأصل ومفاتيح الطبقة بزمنها المحلي؛ تُعرض للمستخدم على محور المشروع بتحويل صريح. التكبير يعيد إسقاط البكسلات ولا يعيد تقريب بيانات الملف.'),('الالتزام','قبل الإفلات يظل التعديل مسودة. الأمر يفحص المراجعة ثم يحفظ قبل الإقرار. فشل الكتابة يعيد الحالة الموثوقة ولا يستهلك Undo. تخطيط ترتيب مسارات أو دمج متداخل لا يعني أن reducer أو المخطط يدعمه.')))
p('11  /  MOTION LAB','المفتاح يملك قيمة، والمنحنى يصف الفترة','مثال من نفس T1: تظهر الطبقة بين 1.200 و4.800 ث. قيم الوقت المرسومة على محور المشروع؛ المفتاح الأول عند 2.400 ث يساوي 1.200 ث محليًا.',img('motion','التحجيم من 110% إلى 125% • المنحنى بين K1 وK2 وليس مسار حركة مكانيًا')+rows(('التأليف','اختر Position / Scale / Rotation / Opacity. أضف معيّنًا عند المؤشر أو حدّد الموجود. حرّك المفتاح أفقيًا لضبط الزمن أو عدّل قيمته رقميًا. النسخ يعاين فرق الأزمنة قبل الالتزام؛ حذف آخر مفتاح يحتاج تعريف وضعية الأساس.'),('تحرير المنحنى','خطي، تثبيت، أو Bézier بمقبضين. المحور الأفقي تقدم الزمن [0،1] والعمودي تقدم القيمة. تقارب المفاتيح يستدعي تكبيرًا أو حقولًا رقمية. يمنع انقلاب الزمن وتصادم المفاتيح؛ لا يتغير طول الفترة لمجرد تحريك ميل المقبض.'),('بوابة القبول','v1 يعتمد وضعيات كاملة واستيفاء خطيًا؛ فصل منحنيات لكل خاصية ونسخ التحريك وBézier أهداف تحتاج مواصفة بيانات وتصدير واختبار قبل إتاحتها. اختبر الزمنين الطرفيين وعينة وسطية في المعاينة وفي الملف الناتج.')))
p('12  /  INSPECTORS','مفتش واحد بأربع لهجات','ثوابت المفتش: هوية العنصر، اسم الخاصية ووحدتها، معاينة المسودة، ثم تأكيد أو إلغاء.',img('properties','رسم الموجة والمؤثرات للتصميم فقط، وليست نتيجة معالجة حقيقية.')+txt('النص العربي: ضبط المحتوى والخط والحجم واللون والمحاذاة والظل والخلفية والمدة؛ اختبار التشكيل والأرقام والنص المختلط في الناتج. الأشكال تبقى عناصر قابلة للتحرير لا ملصقًا مسطّحًا إلا إذا صُرّح بذلك.')+txt('الصوت: استيراد ومعاينة، مستوى وقص وتقسيم، مزامنة رقمية وتلاشٍ مقيّد بالمدة. لا تُشتق الموجة من حركة المؤشر. المؤثرات: بطاقات معاينة منفصلة عن حالة «مطبّق»؛ القناع أو Blend Mode أو الحدود خصائص مرتبطة بالعنصر، والانتقال بين مقطعين مرتبط بوصلة. عند غياب داعم التصيير لا يظهر تطبيق فعّال.'))
p('13  /  EXPORT','الثقة عند آخر خطوة','لا تساوي نهاية التحويل نجاح النشر. النجاح هو ملف مستقل يمكن فتحه، مع بقاء الأصل دون تعديل.',img('export')+rows(('بوابة الإعدادات','في المصدر الواحد يراجع المستخدم النطاق والاتجاه والصوت والوجهة. خيارات الدقة وFPS ومعدل البت وضبط الصوت تظهر فقط عند دعمها والتحقق منها. تقدير الحجم عند معرفة المعدلات: المدة × مجموع البتات/ث ÷ 8 + هامش للحاوية؛ وإلا «غير معروف».'),('الحالات','فحص ← تحويل ← تحقق ونشر ← نجاح. نسبة مجهولة: مؤشر غير محدد. أثناء الإلغاء: «جارٍ الإلغاء» حتى تنظيف المؤقت. المصدر المفقود أو نقص المساحة له إجراء تعافٍ دون الكتابة فوق اللقطة. فتح/مشاركة الناتج مشروطان بربط آمن حقيقي.')))
p('INTERACTION  /  4 BEATS','ما الذي تغيّر عند اللمس؟','الزمن في المثال ثابت بينما يتغير التحديد والنطاق. تُفصل المسودة عن الكتابة إلى الملف.',img('beats','قصة تفاعل ثابتة؛ لا تُقاس منها السرعة أو سلاسة Android.')+rows(('من التصفّح إلى التحديد','تثبت نافذة المعاينة ويتحول إطار العنوان واسم المفتش إلى T1. عند لمس فراغ يُلغى التحديد فقط؛ لا يتغير وقت التشغيل.'),('من المسودة إلى الالتزام','سحب النهاية من 4.800 إلى 4.080 ثانية لا ينقل البداية 1.200. إلغاء يعود إلى 4.800. التأكيد ينتظر إقرار الحفظ قبل عرض الرسالة، وعند الفشل تبقى آخر نسخة موثوقة مع إمكانية إعادة المحاولة.'),('بديل غير حركي','نفس العملية ممكنة باختيار T1 من قائمة الطبقات، وكتابة قيمة النهاية في حقل زمني، ثم تأكيد. لا تتطلب المسودة سحبًا دقيقًا أو تمييز لونين.')))
p('14  /  MOTION & ACCESS','الحركة لغة تغذية راجعة','ابدأ التفاعل بتأكيد قصير، وأنهه بحالة يمكن قراءتها دون الاعتماد على الحركة نفسها.',table(['الحركة','المقترح','ماذا يتغيّر؟'],['ضغط وتحديد','80ms؛ easeOut','ملء خفيف وحدّ مرساة يظهران. لا تحريك لموضع الهدف.'],['درج الخصائص','160ms؛ easeOutCubic','الدرج يتّسع فقط؛ لا إنشاء مشغّل ثانٍ.'],['دخول صفحة','220ms؛ إزاحة اتجاهية 12dp','يحفظ موضع العودة، ولا يغيّر موضع الزمن.'],['سحب أو scrub','مباشر بلا tween','المؤشر يتبع الإصبع. تجميع طلبات seek ثم إرسال الموضع النهائي.'],['نافذة أو تبويب','120ms؛ تلاشي قصير','تركيز على التبويب الجديد ثم العودة لمُطلِق النافذة.'],['تصدير','الأحداث الحقيقية وحدها','لا دوران للعلامة ولا حركة مستمرة لبطاقات غير مرئية.'])+rows(('RTL وLTR','العربية افتراضيًا، English اختياري من الإعدادات. تعكس أدوات التنقّل والهوامش وموضع المفتش. لا تُقلب الصورة أو العلامة أو تشغيل الوسائط؛ الزمن يزيد نحو اليمين في الحالتين. صف عربي قد يلتف، لكن قيمة الزمن وامتداد الملف داخل bdi.'),('إتاحة الاستخدام','التحديد بالاسم والحد وليس باللون فقط؛ لكل أمر تسمية قارئ شاشة وبديل عن السحب. إعلان النجاح مرة، لا كل تحديث وقت. مراعاة تكبير النص 200% والتقليل من الحركة: إزالة الإزاحة وترك التركيز الفوري. اختبار تناسق ARB والتباين وTalkBack لاحق، لا ادعاء بتنفيذه هنا.')))
p('15  /  BRAND IN THE WORLD','هوية تتبع العمل خارج المحرّر','علامة ثابتة، صورة واسعة محايدة، محور ذهبي واحد، ورقم زمن صغير: توقيع يمكن نقله بين الدليل والمتجر والفيلم.',img('campaign','قالب قابل للتحرير • صورة من مواد المشروع، لا لقطة لميزة منتج غير منفذة')+rows(('النسق','واجهة المتجر: صورة أو لقطة موثقة وفائدة محددة لا قائمة وعود. الدليل والاجتماعي: بطاقة مربعة لخطوة واحدة. فيديو العرض والموقع: مساحة أفقية، شعار وقول قصير، وموضع ثابت لترقيم الفصول.'),('ثلاثة أصول قابلة للتعديل','templates/campaign.html للعرض الأفقي، store-portrait.html لبطاقة متجر، guide-card.html للدليل أو النشر الاجتماعي. تُبدّل الصورة والسطر ولا تتشوّه العلامة. عند استخدام تصميم مستقبلي في أي مادة يُكتب «تصوّر تصميمي»؛ لقطات المتجر الفعلية من بناء مثبت فقط.')))
p('16  /  ENGINEERING BOUNDARY','ترجمة التصميم من دون إعادة بناء المحرّك','لم تُعدّل Flutter أو Kotlin أو Media3 أو قناة الاتصال أو عقد المشروع أو الويب أو اختبارات الجهاز.',rows(('الحالة الحالية','مرجع العمل Android مصدر واحد: منتقي رسمي وقراءة URI محفوظة، ExoPlayer للمعاينة، نطاق v1، Transformer للتصدير. سابقًا تحققت حزمة المصدر الواحد على محاكي API 35؛ ذلك ليس إثبات Device Validation على هاتف فعلي.'),('واجهة العرض المقترحة','تبقى Widgets مالكة للتخطيط فقط. يحوّل محوّل presentation واحد state الحالي إلى ViewState منضبط؛ يشتق قدرات الأوامر من التنفيذ. لا مؤقت لكل لوحة، ولا استدعاء Media3 من زر أو قيمة زمن في بطاقة. Controller واحد للمهمة يمنع فقد التقدم عند التدوير.'),('الطبقة الدائمة','Project Contract مرجع البيانات؛ المراجعة عند نجاح الالتزام فقط. مصدر الوسائط ليس نسخة ضمن المشروع. لا تُحفظ مواضع الإرساء كحقول v1؛ لا تضاف طبقات/منحنيات/أوامر غير ممثلة دون سبب ومراجعة واعتماد صريح للتغيير.'),('اختبار القرار قبل الإعلان','مثال منحنى جديد: تعريف التمثيل والتحقق → أمر قابل للإعادة والتراجع → معاينة النظام → تصدير عينات مرجعية → إعادة فتح ومقارنة. وجود رسم أو حفظ JSON وحده لا يثبت وجود التأثير في الفيديو.'),('مخاطر التنفيذ','عرض كل المصغرات أو البطاقة المتحركة دفعة واحدة يستهلك الذاكرة. تحميل قرب مجال الرؤية، خامات محدودة وإبطال رسم المؤشر فقط. مقارنة السلاسة/الذاكرة/الحرارة بالخط الأساس على الجهاز نفسه؛ لا توقع أداء من PNG.'))+note('دعم جهاز لوحي Android ليس دعم Desktop. لا تبديل للمشغل، ولا تغيير للـschemaVersion أو قناة max_editor/single/v1، ولا إيقاف أو تأجيل اختبار جهاز بقرار تصميم.'))
p('17  /  OWNER REVIEW','قرارات تُعرض على المالك','اعتماد المرجع الإستراتيجي لا يعادل اعتماد هذه الرسوم أو تفويض أي تطوير.',table(['القرار المطلوب','التوصية الحالية','ما يتوقف عليه'],['الهندسة النهائية للحرف M','إحضار المرجع أو اعتماد الدراسة من الوصف؛ تثبيت الحبر الواحد والقفل الأفقي.','أيقونة الإصدار وملفات النشر الرسمية'],['الهوية والسرد التسويقي','اعتماد محور الذهب والعبارة الثنائية واستعمال الموضع الزمني في المواد.','قوالب المتجر والدليل والحملات'],['محور الزمن واتجاهه','LTR دائمًا؛ تنعكس ألواح التنقل والقراءة لا الساعة.','ضبط التقاط المقابض والتوطين'],['المرساة والمفتش','هوية T1 واحدة بين الزمن والمعاينة والخصائص؛ درج على الهاتف ولوح جانبي عند الاتساع.','اختبار قابلية العثور على الأداة'],['حدود الاتساع','قبول العتبات كفرضيات، ثم قياس 320/390dp وهاتف أفقي ولوحي مع نص كبير.','قرار تثبيت/طي الألواح'],['أولوية التحريك والتأثيرات','مواصفة بيانات مستقلة قبل Bézier وأقنعة ومسارات صوت. لا قبول وظيفي للنموذج.','قبول كل نظام لاحق'],['الكمبيوتر','دراسة إدخال وتخزين ومعالجة منفصلة. لا منصة أو موعد إطلاق معتمد.','أي نموذج تقني مستقل'])+h('التوصية التالية، وليست بدءًا للعمل')+txt('يراجع المالك نفس المهمة في اللوحات الأربع: أين المحدّد؟ ما الزمن؟ كيف يخرج من المسودة دون تغيير المشروع؟ بعد اعتماد التصميم ونتائج Device Validation يلزم تكليف منفصل حتى لتنفيذ المكونات الأولية.'))
p('18  /  HANDOFF','محتويات التسليم وحدوده','هذه حزمة أصول ومواصفات قابلة للتحرير، لا تطبيق تجريبي.',rows(('ما أُنجز','تطوير هوية المرحلة A إلى نظام منتج مترابط. ٤ نماذج أجهزة، ٣ لوحات للأنظمة ولوحة لحالات التفاعل، ٣ قوالب اتصال خارجي، علامة قابلة لإعادة التلوين، و٣٤ رمزًا متجهيًا. النص يصف السلوك والحالات غير المرئية في اللوحات.'),('الأصول','assets/logo: المتجه المعدني والأحادي والعكسي، قفل فاتح وداكن، طبقات ودراسة أيقونة Android. assets/icons.svg وsymbols-source.json للمسارات. assets/tokens.json للأدوار والمقاييس والحركة والتكيف. assets/type تشمل أوزان Tajawal الثلاثة وترخيصها، ونسخ Plex المرجعية بترخيصها، وmedia صورة الجبل.'),('المصادر','boards: HTML/CSS قابلة للتحرير لكل جهاز وللحركة والخصائص والتصدير. templates: نماذج التسويق. models: صور PNG مرجعية. source: مصادر توليد النماذج والوثيقة. report.html مصدر مستقل عن أي خادم عند وجود المجلدات المجاورة، وPDF للقراءة.'),('ما جرى فحصه','فحص بنية JSON وSVG وأسماء الرموز، ورسم ملفات HTML في Chromium لإخراج صور اللوحات والـPDF. فحص احتواء صفحات التقرير وفتح أرشيف الأصول. هذه فحوص مستندات ورسوم، وليست اختبارات أداء أو تشغيل لتطبيق.'),('غير متاح أو غير منفّذ','لا صورة شعار أصلية أو اعتماد فني نهائي لها. لا تحقق جهاز حقيقي جديد ولا تأكيد اكتمال اختبار جارٍ. قيم ومشاريع النماذج افتراضية، ولا استيراد أو تصدير أو مزج فعلي من HTML، ولا تطبيق Desktop. لا ملفات تطبيق أو اختبارات أو مهام CI معدلة.'))+note('نقطة التوقف: مراجعة المالك. تحتفظ المرحلة A والحزم التقنية السابقة بملفاتها؛ لا تنفّذ مرحلة لاحقة تلقائيًا.'))
p('TYPE PROOF  /  A–B','الخطّان في شاشة واحدة','شاشة مراجعة القص نفسها عند عرض 320px وحجم نص 100%. النص والصورة والأبعاد واحدة؛ لكل عائلة أوزانها الأصلية.', '<div class="compare"><figure><img src="evidence/typography/Tajawal.png"><figcaption>Tajawal · التصميم المقترح</figcaption></figure><figure><img src="evidence/typography/Plex.png"><figcaption>IBM Plex Sans Arabic · المرجع السابق</figcaption></figure></div>'+rows(('الاختيار التصميمي','أوصي بتجوال: في العينة يفصل الوزن المتوسط تسمية الزر عن المتن دون كثافة شبه العريض، ويعطي تباعد الحروف الداخلية مساحة تُميّز شكل الحرف عند القراءة. استخدام العريض محدود بالعناوين القصيرة. هذا حكم بصري على العينات وليس قياسًا لتفضيل المستخدمين.'),('المقابل الذي نقبله','تجوال ليس أضيق: قياس عرض «تصدير الجزء المحدّد» بوزن Regular وحجم 16px أعطى 125px مقابل 117px لـPlex. في عرض 320px عند تكبير النص إلى 130% التفّت الفقرة إلى أربعة أسطر بتجوال وثلاثة بالمرجع؛ نسمح بالالتفاف بدل تصغير الخط أو اقتطاع النص.')))
p('TYPE VALIDATION  /  HANDOFF','تقرير تعديل الخط','نطاق المراجعة: الطباعة العربية والنصوص المختلطة فقط. الهوية والهندسة اللونية وترتيب الشاشات لم يُعد تصميمها.',rows(('ما تغير','ص٤ وكل الرسوم المشتقة ولوحات HTML وقوالب العلامة وفهرس النماذج ومصدر التقرير. حُدّث وصف الخط في مفتش النص وDesign Tokens. القراءة من اليمين للنص العربي ومن اليسار للزمن؛ الرقم الزمني يبقى أحادي العرض بدل تبدل عرض المؤشر بتغيّر الأرقام.'),('طريقة المقارنة','Chromium، شاشات اختبار HTML بعروض 320 و360 و390 CSS px × 640 وبتكبير النص إلى 100% و130% و200%؛ لكل حالة عائلة Tajawal ثم نظير Plex. فُحص تحميل الأوزان، وعرض الفقرة، وامتداد الملف المختلط، وحقل الاسم، وزرّا التصدير/الرجوع في عينة مراجعة القص.'),('مشكلة ظهرت والإصلاح','فشل النموذج الأول عند تكبير 200% لأن الحقل الأحادي لم يعرض اسمه كاملاً. استُبدل في عينة اختبار الضغط بحقل متعدد السطور، وأُتيح التفاف النقل والأزرار مع تجميع امتداد الملف. لا يُفترض نجاح كل شاشة في التطبيق لمجرد تحسين العينة.'),('النتيجة القابلة للإعادة','نجحت الحالات الـ18 النهائية في حدود الاختبار: لا تجاوز أفقي للحاويات المقيسة؛ قيمة الحقل كاملة، وأهداف الزرين ≥48 CSS px، واتجاه كود الوقت LTR. وعلى لوحة المحرّر نفسها بعروض 320 و360 و390px أكد المتصفح استخدام Tajawal فعليًا للعنوان دون تجاوز الحاويات المقيسة في شرائط الأدوات والنقل والمفتش. نتائج المحاولة الأولى والنهائية مرفقة.'),('الترخيص والحدود','Tajawal من Boutros International بترخيص SIL Open Font License 1.1. الأوزان الأصلية ومصدرها المثبّت ونص الترخيص في assets/type/tajawal. Plex للمقارنة فقط وبترخيصه المرفق. هذه مراجعة مستندات، لا اختبار Flutter أو هاتف حقيقي. لم يُمسّ العقد أو المحرك أو قناة الاتصال أو Device Validation.'))+note('قرار المراجعة: هل يعتمد المالك Tajawal بهذه الأوزان؟ لا انتقال إلى التطبيق دون موافقة مستقلة.'))
css='''@import url('assets/type/families.css');@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;background:#dfddd5;font:16px/1.65 Tajawal,Arial,sans-serif;color:#221f19}section{background:#f8f6ef;position:relative;width:210mm;height:296.8mm;margin:auto;padding:11mm 13mm 17mm;break-after:page}section:last-child{break-after:auto}.mast,footer{display:flex;justify-content:space-between;align-items:center;color:#676356;border-bottom:1px solid #c8c3b4;font-size:12px;padding:5px 0 9px;margin-bottom:18px}.mast b,.tag{direction:ltr;unicode-bidi:isolate;font:600 11px Arial;letter-spacing:2px}.tag{color:#82611c}.mast img{height:25px;vertical-align:middle}footer{position:absolute;right:13mm;left:13mm;bottom:7mm;margin:0;border:0;border-top:1px solid #c8c3b4;padding:7px 0 0}.pageNo{font:14px monospace;color:#786c53}h1{font-size:32px;line-height:1.35;margin:8px 0}h2{font-size:21px;margin:20px 0 7px}p{margin:8px 0}.lead{font-size:17px;color:#585447;line-height:1.6;margin:10px 0 17px}dl{margin:10px 0}dt{font-weight:500;border-top:1px solid #dad5c8;padding-top:9px;font-weight:500;color:#75591c}dd{margin:3px 0 12px}aside{border-inline-start:3px solid #b78b29;background:#ece6d5;padding:12px 15px;margin:15px 0}figure{margin:14px 0;text-align:center}figure img{max-width:100%;max-height:430px;object-fit:contain;border-radius:8px}figcaption{font-size:12px;color:#6e685a}table{border-collapse:collapse;width:100%;font-size:14px;margin:14px 0}td,th{padding:8px 7px;text-align:start;vertical-align:top;border-bottom:1px solid #d0cab9}th{background:#24251f;color:#fff}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.cell{padding:11px 14px;background:#eeebdf;border-radius:8px}.logoStrip{display:flex;background:#ded9ca;border-radius:8px;padding:12px;gap:12px}.logoStrip img{width:49%}.swatches{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.swatches div{border:1px solid #d0cab9;border-radius:6px;overflow:hidden;padding-bottom:4px;text-align:center}.swatches i{display:block;height:20px}.swatches small{display:block;font-size:11px}.swatches bdi{font:13px monospace}.atlas{display:grid;grid-template-columns:repeat(7,1fr);gap:3px;padding:12px;background:#101010;border-radius:8px}.atlas div{color:#b8b2a5;text-align:center;background:#191919;padding:5px}.atlas svg{fill:none;stroke:currentColor;stroke-width:1.7;stroke-linejoin:round;stroke-linecap:round;width:22px;height:22px;display:block;margin:0 auto}.atlas small{font-size:11px}.phoneSpread{display:grid;grid-template-columns:245px 1fr;gap:20px;align-items:start}.phoneSpread img{max-height:none;width:100%}.dark{background:#101010;color:#fff}.dark .lead,.dark .mast,.dark footer{color:#b8b2a5}.dark aside{background:#211b10}.dark h1{font-size:54px;color:#f5d77e}.cover{height:315px;background:radial-gradient(ellipse,#302719,#101010 66%);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px}.cover img{width:130px}.cover b{font:600 38px Arial;letter-spacing:5px}.cover small{font:10px monospace;color:#b8b2a5;letter-spacing:2px}''';
css+=' .compare{display:flex;justify-content:center;gap:20px}.compare figure{margin:4px 0 8px}.compare img{height:380px;width:auto}h1,h2{font-weight:700}'
(R/'report.html').write_text('<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>MAX EDITOR — Brand &amp; Product Design System</title><style>'+css+'</style>'+''.join(f'<section class="{"dark" if dark else ""}"><header class="mast"><span>دليل هوية المنتج • 1.0</span><b>MAX EDITOR　 /　 DESIGN</b></header><main><div class="tag">{tag}</div><h1>{title}</h1><p class="lead">{lead}</p>{body}</main><footer><span>تصوّر للمراجعة • لا يمثل بناءً قابلًا للتشغيل</span><bdi class="pageNo">{i:02} / {len(pages):02}</bdi></footer></section>' for i,(tag,title,lead,body,dark) in enumerate(pages,1))+'</html>');print(len(pages),'pages')
